#!/usr/bin/env python3
"""Regenerate the landing page from the already collected local subject manifest."""
from pathlib import Path
from collections import OrderedDict
import json,html
ROOT=Path(__file__).resolve().parents[1];E=html.escape
subjects=json.loads((ROOT/'subjects.json').read_text());groups=OrderedDict()
for s in subjects:groups.setdefault(s['category'],[]).append(s)
nav='<a href="#subjects" data-branch="all" aria-current="true"><span>All mathematics</span><span class="count">17</span></a>'
sections=[]
for category,items in groups.items():
 title=items[0]['categoryTitle'];nav+=f'<a href="#{category}" data-branch="{category}" aria-current="false"><span>{E(title)}</span><span class="count">{len(items)}</span></a>'
 cards=[]
 for s in items:
  index=subjects.index(s)+1;search=s['title']+' '+s['categoryTitle']+' '+' '.join(s['regions']);topics=' · '.join(s['regions'][:3]);more=len(s['regions'])-3
  projects=f'<div class="card-projects">{s["projectCount"]} selected theorem walkthroughs · PDF reports</div>' if s.get("projectCount") else ""
  cards.append(f'''<a class="subject-card" href="{s['path']}" data-category="{category}" data-title="{E(s['title'])}" data-order="{index}" data-search="{E(search)}"><div class="card-preview"><img src="{s['preview']}" alt="" width="700" height="220" loading="lazy"></div><div class="card-body"><span class="card-code">ATLAS {index:02d} / {len(s['regions'])} REGIONS</span><h3>{E(s['title'])}</h3><p class="card-topics">{E(topics)}<br>+ {more} more regions</p><div class="card-counts">{s['nodes']} mathematical objects · {s['edges']} connections</div>{projects}<div class="card-foot"><span>Explore this subject</span><span aria-hidden="true">↗</span></div></div></a>''')
 sections.append(f'<section id="{category}" class="subject-group"><div class="category-heading"><h2>{E(title)}</h2><span class="group-count">{len(items)} subject'+('s' if len(items)!=1 else '')+'</span></div><div class="subject-grid">'+''.join(cards)+'</div></section>')
page='''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Explore 17 independent Meta-Math subject atlases: definitions, theorems and the dependencies connecting mathematical ideas."><meta name="theme-color" content="#176951"><title>Meta-Math · Mathematics Atlas</title><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="assets/dashboard.css"></head>
<body><a class="skip" href="#subjects">Skip to subjects</a><header class="site-header"><div class="shell header-inner"><a class="brand" href="index.html" aria-label="Meta-Math home"><img src="assets/favicon.svg" width="43" height="43" alt=""><span>Meta-Math<small>THE MATHEMATICS ATLAS</small></span></a><nav class="header-links" aria-label="Page navigation"><a href="#subjects">Explore subjects</a><a href="#how-to-read">How to read the maps</a></nav></div></header>
<main class="shell"><section class="hero"><div><span class="eyebrow">A LIBRARY OF CONNECTED IDEAS</span><h1>Every theorem has<br>a <em>path behind it.</em></h1><p>Choose a mathematical subject and explore the ideas that support it. Move from definitions to major theorems, trace their dependencies, and discover where each result leads. Then enter a subject’s project dashboard to explore five complete proofs through their local agents.</p></div><div class="hero-stats" aria-label="Library statistics"><div class="stat"><strong>17</strong><span>independent subject atlases</span></div><div class="stat"><strong>6</strong><span>mathematics branches</span></div><div class="stat"><strong>968 <span style="display:inline;font:20px Georgia;color:#92a68d">/</span> 1,190</strong><span>mathematical objects / selected connections</span></div></div></section>
<section class="browse" id="subjects" aria-label="Subject directory"><aside class="sidebar"><h2>Mathematics branches</h2><nav class="branch-nav" aria-label="Filter by mathematics branch">NAV</nav><div class="side-note"><strong>One subject. One landscape.</strong>Each atlas opens as its own workspace, with local definitions, results, references, a graduate book outline, and five selected theorem walkthroughs.</div></aside><div class="catalog"><div class="controls"><div class="search-field"><label for="subject-search">Find your next subject</label><div class="search-box"><svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><circle cx="10" cy="10" r="6.5" stroke-width="1.5"/><path d="m15 15 5 5" stroke-width="1.5"/></svg><input id="subject-search" type="search" placeholder="Search subjects or regions — Fourier, Lie, topology…" autocomplete="off"></div></div><div class="sort-field"><label for="sort">Order within each branch</label><select id="sort"><option value="curriculum">Curriculum order</option><option value="alphabetical">Alphabetical</option></select></div></div><div class="result-line"><span id="result-count" role="status" aria-live="polite">17 of 17 subjects</span><button id="clear" hidden>Clear filters</button></div><noscript><p>The full subject directory is available below. Enable JavaScript for filtering and the interactive graph explorers.</p></noscript>SECTIONS<div id="empty" class="empty" hidden><h2>No matching subjects</h2><p>Try a broader subject or region name, or return to the full library.</p><button id="empty-clear">Show all subjects</button></div></div></section>
<section class="explanation" id="how-to-read"><div><span class="eyebrow">FROM THE BIG PICTURE TO A SINGLE RESULT</span><h2>Follow the reasoning.</h2><p>Each atlas maps selected mathematical relationships. The book view provides a separate guide to the subject’s graduate syllabus.</p></div><div class="steps"><article><span class="step-number">01</span><h3>Choose a landscape</h3><p>Open a subject, then use its regions to move from foundations to advanced topics. Pan and zoom to explore the full map.</p></article><article><span class="step-number">02</span><h3>Inspect the support</h3><p>Select a node for its statement, assumptions and references. Arrow types distinguish definitions, proof ingredients, consequences and conceptual bridges.</p></article><article><span class="step-number">03</span><h3>Step inside a proof</h3><p>Choose “Explore five selected theorems” in any atlas. Open a project, follow its local agents and five faculties, and read the complete proof or PDF report.</p></article></div></section>
<footer class="site-footer"><p>Meta-Math · A library for exploring mathematical reasoning.<br>These curated maps record selected dependencies, not exhaustive or formally verified proofs. Each subject remains independent; shared ideas are counted locally in each atlas. Each subject includes five complete theorem walkthroughs, with local five-faculty workflows and downloadable reports.</p><a href="README.md">Project & hosting guide ↗</a></footer></main><script src="assets/dashboard.js"></script></body></html>'''
(ROOT/'index.html').write_text(page.replace('NAV',nav).replace('SECTIONS','\n'.join(sections)).replace('968',f'{sum(s["nodes"] for s in subjects):,}').replace('1,190',f'{sum(s["edges"] for s in subjects):,}')+'\n')
(ROOT/'.nojekyll').touch()
print('Built master dashboard for',len(subjects),'subjects')
